'use strict';
const Vale8={
 store(){return S.vale8??={version:1,posts:[],deferred:[],streaks:{},events:[]};},
 variants:['ЭТО МЕНЯЕТ ВСЁ!','СЛЕДИМ ЗА РАЗВИТИЕМ СОБЫТИЙ!','СЦЕНА ОБСУЖДАЕТ ЭТУ НОВОСТЬ!','СЕРЬЁЗНЫЙ ПОВОРОТ!','НОВАЯ ГЛАВА НАЧИНАЕТСЯ!','ДЕТАЛИ УЖЕ ПОЯВЛЯЮТСЯ!','ГРОМКОЕ СОБЫТИЕ!','ВНИМАНИЕ НА ЭТУ КОМАНДУ!','СЕГОДНЯ О НИХ ГОВОРЯТ ВСЕ!','БОЛЬШИЕ ПЕРЕМЕНЫ!','ЭТА ИСТОРИЯ ПРОДОЛЖАЕТСЯ!','СОБЫТИЯ НАБИРАЮТ ОБОРОТЫ!'],
 add(id,kind,title,data={}){const m=this.store();if(m.posts.some(p=>p.id===id))return;let h=0;for(const c of id)h=(h*31+c.charCodeAt(0))>>>0;m.posts.push({id,kind,title:(title+' '+this.variants[h%12]).toLocaleUpperCase(),day:S.day,tag:this.variants[h%12],...data});},
 deals(){for(const d of S.market7?.deals||[]){const p=S.players[d.player];if(!p)continue;const stage=d.stage,kind=stage==='inquiry'?'interest':['signed'].includes(stage)?null:['rejected','cancelled','expired','invalid'].includes(stage)?'failed':['agreed','player_pending','player_counter'].includes(stage)?'close':['club_pending','club_agreed'].includes(stage)?'talk':null;if(!kind)continue;this.add('deal:'+d.id+':'+kind,kind,p.name+(kind==='failed'?' — ПЕРЕХОД НЕ СОСТОЯЛСЯ':kind==='interest'?' — ИНТЕРЕС К ПЕРЕХОДУ':kind==='close'?' — БЛИЗКО К СОГЛАШЕНИЮ':kind==='confirmed'?' — СДЕЛКА ЗАКРЫТА!':' — ПЕРЕГОВОРЫ ИДУТ'),{player:p.name,photo:photo20(p)||null,from:d.source,to:d.buyer,fee:kind==='confirmed'?d.fee:null,body:d.message});}},
 tick(){this.deals();const m=this.store();for(const d of m.deferred)if(d.due<=S.day)d.visible=true;},
 artwork(p){const club=id=>S.teams[id]?clubAvatar12(S.teams[id],true):'<span>FA</span>';return '<article class="vale-post"><header><b class="vale-avatar">AV</b><div><strong>ALEX VALE <span>✓</span></strong><small>VALE INSIDE · '+esc(date(p.day))+'</small></div></header><div class="vale-art '+(p.kind==='failed'?'vale-failed':'')+'"><div class="vale-mast">'+(['upset','streak'].includes(p.kind)?'VALE / SPECIAL REPORT':'BREAKING 🚨')+'<span>'+esc({interest:'ИНТЕРЕС',talk:'ПЕРЕГОВОРЫ',close:'БЛИЗКО К СОГЛАШЕНИЮ',confirmed:'ПОДТВЕРЖДЕНО',failed:'ПЕРЕХОД СОРВАЛСЯ',upset:'СЕНСАЦИЯ',streak:'ЧЕМПИОНСКАЯ СЕРИЯ'}[p.kind])+'</span></div><h2>'+esc(p.title)+'</h2><div class="vale-visual">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="'+esc(p.player||'')+'" loading="lazy">':'')+(p.trophy?Trophy4B.sprite(p.trophy):'')+'<div>'+club(p.from)+'<b>→</b>'+club(p.to)+'</div></div>'+(p.fee!=null?'<strong class="vale-fee">'+cash(p.fee)+'</strong>':'')+'<p>'+esc(p.body||p.tag).toLocaleUpperCase()+'</p><footer>VALE INSIDE / '+esc(p.tag)+'</footer></div></article>';},
 view(){const posts=S.vale8?.posts||[];return '<section class="vale-feed"><h1>VALE INSIDE</h1><p>АЛЕКС ВЕЙЛ · ИНСАЙДЫ И ГЛАВНЫЕ СОБЫТИЯ ВАШЕЙ КАРЬЕРЫ</p>'+posts.slice(-20).reverse().map(p=>this.artwork(p)).join('')+(posts.length?'':'<p>Первые материалы появятся по ходу переговоров и турниров.</p>')+'</section>';}
};
const entryBeforeVale8=transferEntryV1;transferEntryV1=function(...a){const r=entryBeforeVale8(...a),e=S.transfersV1?.[0];if(e?.type==='sign'&&e.fee>0){const p=S.players[e.player],id=S.transfersV1.length,m=Vale8.store(),post=S.clubNews60a?.posts.find(p=>p.id===id);Vale8.add('transfer:'+id,'confirmed',e.name+' — СДЕЛКА ЗАКРЫТА!',{player:e.name,photo:photo20(p)||null,from:post?.from?.id??e.from??null,to:e.to,fee:e.fee,body:'ОФИЦИАЛЬНОЕ ПРЕДСТАВЛЕНИЕ ОЖИДАЕТСЯ В БЛИЖАЙШИЕ ДНИ.'});m.deferred.push({id,due:S.day+2+id%2,to:e.to,player:e.player,visible:false});}return r;};
const newsItemsBeforeVale8=ClubNews60A.items;ClubNews60A.items=function(){const m=S.vale8;return newsItemsBeforeVale8.call(this).filter(p=>p.kind||!m?.deferred.some(d=>d.id===p.id&&!d.visible));};
const recordBeforeVale8=recordNode6;recordNode6=function(a,n,...args){const e=S.events.find(e=>e.id===a.event);if(e&&!e.valeRanks8)e.valeRanks8=a.entrants.slice().sort((x,y)=>(S.teams[y].career13?.seasonPoints||0)-(S.teams[x].career13?.seasonPoints||0)||(S.teams[y].career13?.elo||0)-(S.teams[x].career13?.elo||0)||x-y);const r=recordBeforeVale8(a,n,...args),pair=n.pair.map(v=>resolve6(a,v));for(const d of S.vale8?.deferred||[])if(pair.includes(d.to)&&roster(S.teams[d.to]).some(p=>p.id===d.player))d.visible=true;return r;};
const finishBeforeVale8=finishEvent6;finishEvent6=function(a,...args){const r=finishBeforeVale8(a,...args),e=S.events.find(e=>e.id===a.event);if(!e?.done||Qualifiers.isRegional(e))return r;const m=Vale8.store();if(m.events.includes(e.id))return r;m.events.push(e.id);for(const id of a.entrants){m.streaks[id]=id===e.champion?(m.streaks[id]||0)+1:0;}const team=S.teams[e.champion],rank=(e.valeRanks8||a.entrants).indexOf(e.champion),upset=rank>=a.entrants.length/2,streak=m.streaks[e.champion];if(upset||streak>=2)Vale8.add('event:'+e.id,streak>=2?'streak':'upset',team.name+' — '+(streak>=2?streak+' ТРОФЕЯ ПОДРЯД!':'ОНИ ЭТО СДЕЛАЛИ! СЕНСАЦИОННЫЙ ЧЕМПИОН!'),{from:null,to:team.id,trophy:Trophy4B.select(e).key,body:e.name+' · '+(upset?'ПОБЕДА КОМАНДЫ ИЗ НИЖНЕЙ ПОЛОВИНЫ ПОСЕВА. ':'')+'КУБОК ОТПРАВЛЯЕТСЯ К ЧЕМПИОНАМ!'});return r;};
const tickBeforeVale8=tick;tick=function(...a){const r=tickBeforeVale8(...a);Vale8.tick();return r;};
